const FLAG_TO_NAME = new Map([
  ['--a', 'a'],
  ['--b', 'b'],
  ['--c', 'c'],
  ['--d', 'd'],
]);

const REQUIRED_FLAGS = ['--a', '--b', '--c', '--d'];

function getProgramName(argv) {
  const scriptPath = argv[1] ?? 'test12.mjs';
  const normalized = String(scriptPath).replace(/\\/g, '/');
  const slashIndex = normalized.lastIndexOf('/');
  return slashIndex === -1 ? normalized : normalized.slice(slashIndex + 1);
}

function usageText(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D\n`;
}

function helpText(programName) {
  return (
    `usage: ${programName} [-h] --a A --b B --c C --d D\n\n` +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C\n' +
    '  --d D\n'
  );
}

function parseHelpToken(token) {
  if (token === '-h') {
    return { kind: 'help' };
  }

  if (!token.startsWith('--')) {
    return null;
  }

  const equalsIndex = token.indexOf('=');
  const optionPart = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  if (!'--help'.startsWith(optionPart) || optionPart === '--') {
    return null;
  }

  if (equalsIndex !== -1) {
    return {
      kind: 'help-argument-error',
      explicitArgument: token.slice(equalsIndex + 1),
    };
  }

  return { kind: 'help' };
}

function parseKnownOption(token) {
  const equalsIndex = token.indexOf('=');
  const optionPart = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const name = FLAG_TO_NAME.get(optionPart);
  if (name === undefined) {
    return null;
  }

  return {
    flag: optionPart,
    name,
    inlineValue: equalsIndex === -1 ? null : token.slice(equalsIndex + 1),
  };
}

function writeError(programName, message) {
  process.stderr.write(usageText(programName));
  process.stderr.write(`${programName}: error: ${message}\n`);
  return {
    ok: false,
    exitCode: 2,
  };
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv);
  const args = argv.slice(2);
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
    d: undefined,
  };
  const unknown = [];

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (token === '--') {
      unknown.push(...args.slice(index));
      break;
    }

    const help = parseHelpToken(token);
    if (help !== null) {
      if (help.kind === 'help') {
        process.stdout.write(helpText(programName));
        return {
          ok: false,
          exitCode: 0,
        };
      }

      return writeError(
        programName,
        `argument -h/--help: ignored explicit argument '${help.explicitArgument}'`,
      );
    }

    const option = parseKnownOption(token);
    if (option !== null) {
      if (option.inlineValue !== null) {
        values[option.name] = option.inlineValue;
        continue;
      }

      const next = args[index + 1];
      if (next === undefined || next.startsWith('-')) {
        return writeError(programName, `argument ${option.flag}: expected one argument`);
      }

      values[option.name] = next;
      index += 1;
      continue;
    }

    unknown.push(token);
    if (token.startsWith('-')) {
      const next = args[index + 1];
      if (next !== undefined && !next.startsWith('-')) {
        unknown.push(next);
        index += 1;
      }
    }
  }

  const missing = REQUIRED_FLAGS.filter((flag) => {
    return values[FLAG_TO_NAME.get(flag)] === undefined;
  });

  if (missing.length > 0) {
    return writeError(
      programName,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (unknown.length > 0) {
    return writeError(programName, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return {
    ok: true,
    exitCode: 0,
    values,
  };
}

