  try {
    return decodeURIComponent(normalized);
  } catch {
    return normalized.replace(/(?:%[0-9A-Fa-f]{2})+/g, (chunk) => {
      try {
        return decodeURIComponent(chunk);
      } catch {
        return chunk;
      }
    });
  }
}

