  ['%21', '!'],
  ['%24', '$'],
  ['%26', '&'],
  ['%27', "'"],
  ['%28', '('],
  ['%29', ')'],
  ['%2A', '*'],
  ['%2B', '+'],
  ['%2C', ','],
  ['%3B', ';'],
  ['%3D', '='],
  ['%3A', ':'],
