import {
  parsePathSegments,
  parseQueryItems,
  serializePathSegments,
  serializeQueryItems,
} from './fragment_parts.mjs';

export class Fragment {
  constructor(fragmentText = '') {
    const source = String(fragmentText);
    const separatorIndex = source.indexOf('?');
    const rawPath = separatorIndex === -1 ? source : source.slice(0, separatorIndex);
    const rawQuery = separatorIndex === -1 ? '' : source.slice(separatorIndex + 1);

    this.pathSegments = parsePathSegments(rawPath);
    this.queryItems = parseQueryItems(rawQuery);
    this.attributes = new Map();
  }

  setAttribute(name, value) {
    this.attributes.set(String(name), value);
    return undefined;
  }

  add(path = '') {
    const newSegments = parsePathSegments(path);
    if (newSegments.length > 0) {
      this.pathSegments.push(...newSegments);
    }

    return this;
  }

  set(path = '', args) {
    this.pathSegments = parsePathSegments(path);
    this.queryItems = args === undefined ? [] : parseQueryItems(args);
    return this;
  }

  toString() {
    const path = serializePathSegments(this.pathSegments);
    const query = serializeQueryItems(this.queryItems);

    if (path !== '' && query !== '') {
      return `${path}?${query}`;
    }

    if (path !== '') {
      return path;
    }

    return query;
  }
}

