import { Fragment } from './fragment.mjs';

export class FurlLike {
  constructor(urlText) {
    const source = String(urlText);
    const fragmentIndex = source.indexOf('#');

    this.base = fragmentIndex === -1 ? source : source.slice(0, fragmentIndex);
    this.fragment = new Fragment(fragmentIndex === -1 ? '' : source.slice(fragmentIndex + 1));
  }

  get url() {
    const fragmentText = String(this.fragment);
    if (fragmentText === '') {
      return this.base;
    }

    return `${this.base}#${fragmentText}`;
  }
}

